insert into public.docs (collection, scope, id, data, updated_by, updated_at) values
  ('reviews', '', '595uq2q6m2apf6tyd3wh', '{"course": "진단의 기본", "prof": "김원화", "text": "수업도 무난하시고 문제도 무난하게 나왔습니다. 수업 중에 매뉴얼 읽는 내용 + 추가 설명한 부분에서 내시는 스타일인듯합니다.", "updatedAt": "2026-10-16T05:40:51.620Z"}'::jsonb, 'evenstar1031', now()),
  ('reviews', '', '8k7ks4j0mww02z2ly6ke', '{"course": "치료의 기본", "prof": "김혜진", "text": "대출 하도 많이 해서 출석 부르는 로망이 있으시답니다.. 전자 출결 아예 안하시고 그냥 수업 끝에 호명하시네요", "updatedAt": "2026-10-20T00:18:14.440Z"}'::jsonb, 'evenstar1031', now()),
  ('reviews', '', '8kxvfrgljao3p6unl7r8', '{"course": "치료의 기본", "prof": "황덕비", "text": "계산 문제 좋아하시네요,,, 아직 2년치밖에 없어서 그 전 교수님이 냈던 문제 바꿔서 내시는 느낌입니다", "updatedAt": "2026-10-28T15:37:24.213Z"}'::jsonb, 'evenstar1031', now()),
  ('reviews', '', 'd1dd61soa84i6cabpu7k', '{"course": "치료의 기본", "prof": "박준모", "text": "말이 많으시지만,,, 설명하신 데서 문제를 내는 것 같네요... 수업 듣기 참 힘듭니다.", "updatedAt": "2026-10-26T05:11:31.783Z"}'::jsonb, 'evenstar1031', now()),
  ('reviews', '', 'ed9yhybaq01t8ehgs1vv', '{"course": "치료의 기본", "prof": "정훈", "text": "1층에서 탁구 치고 있으면 오셔서 같이 치자고 하십니다. 그리고 수업도 야무지시니까 수업 들어보는 것도 도움이 되는 듯하네요", "updatedAt": "2026-10-26T05:12:22.456Z"}'::jsonb, 'evenstar1031', now()),
  ('reviews', '', 'ezp33o6f40youq3q9s4l', '{"course": "치료의 기본", "prof": "전영훈", "text": "차기 병원장님이라는데요,,, 수업은 40분 정도만에 끝내주십니다. 설명한 내용에서 문제도 나오는 것 같아요", "updatedAt": "2026-10-26T01:13:59.681Z"}'::jsonb, 'evenstar1031', now()),
  ('reviews', '', 'omeuz3uuaybamyq6ulvb', '{"course": "진단의 기본", "prof": "곽지혜", "text": "수업때는 GOAT였으나 시험 보고 나서는 의문이 들었던 교수님이네요. 이비인후과가 너무 마이너해서 다 알 필요가 없으니 수업 들어오자마자 시험 4문제 파일 보여주시고는 이대로 문제 나오니까 답만 외우면 됩니다.라고 하셨는데,,, 시험을 쳐보니까 2문제만 그대로 나오고... 답을 외웠던 나머지 2문제는 없었네요,,, 너무 믿지는 마세요 ㅠ", "updatedAt": "2026-10-16T05:40:10.330Z"}'::jsonb, 'evenstar1031', now()),
  ('reviews', '', 'qd39a8ustp2wocqb5mrg', '{"course": "진단의 기본", "prof": "고혜진", "text": "작년 수업 때는 영상 찍는 숙제 내주시고 대출도 조금 엄격하게 잡으셨는데 이번에 담당하신 수업이 피로 파트라 별 어려운 내용 없이 수업도 일찍 끝내주셨습니다. 그런데 문제는 쉽지는 않았던 것 같아요. 매뉴얼에 있는 내용 알아야 풀 수 있는 느낌?", "updatedAt": "2026-10-16T05:33:42.884Z"}'::jsonb, 'evenstar1031', now()),
  ('reviews', '', 'r2at9ncd40nsmmln4fzt', '{"course": "진단의 기본", "prof": "원동일", "text": "진검 쉽지 않습니다. 매뉴얼 자체가 불친절하고 내용도 공부하기 애매한데 수업시간에 언급한 내용만 내시니까 그 부분 위주로 공부하고 기출 잘 공부해가면 문제가 없을 듯하네요", "updatedAt": "2026-10-20T20:14:31.314Z"}'::jsonb, 'evenstar1031', now()),
  ('reviews', '', 'sh0y9s76g5pttaqbastt', '{"course": "진단의 기본", "prof": "김혜정", "text": "출튀/대출 주의... 중간중간에 이름 불러보시는데 한 두명 걸리면 쉬는시간에 전수조사 하십니다... 가만히 앉아서 딴짓하더라도 왠만하면 교실 안에 있는게 좋을 듯 하네요", "updatedAt": "2026-10-16T02:19:16.425Z"}'::jsonb, 'evenstar1031', now()),
  ('reviews', '', 'v1ix8ha7el7jfy24l139', '{"course": "진단의 기본", "prof": "고판우", "text": "별다른 특징이 없습니다. 그냥 신경 경로 암기하고 다른 부분 공부하는 것처럼 하시면 특이사항은 없습니다.", "updatedAt": "2026-10-16T02:18:19.340Z"}'::jsonb, 'evenstar1031', now()),
  ('memos', 'evenstar1031', '2026-09-21', '{"text": "OT는 시험범위 아님\n이장훈T: 혈압 관련해서 항상 문제를 지저분하게 출제하셨다고 하심\n최선하T: 중요한 거 조금 찝어주시고, 매뉴얼이 아예 바뀌었음"}'::jsonb, 'evenstar1031', now()),
  ('memos', 'evenstar1031', '2026-09-28', '{"text": "심잡음 TBL (김남균pf): 기출 문제 참고해서 공부하기"}'::jsonb, 'evenstar1031', now()),
  ('memos', 'evenstar1031', '2026-09-29', '{"text": "목덩이 CP (곽지혜pf): 4문제 동일하게 출제 예정 - 번호도 동일하게 낸다고 하심 (기출이 아니라 그냥 시험문제를 워드 파일로 보여주시는 걸 알아야함)\n운동실조 TBL (고판우pf): 각 조에서 OSCE 문제를 만들어보고, 2-3조 정도 발표시킬 예정"}'::jsonb, 'evenstar1031', now()),
  ('sem1', '', 'pharm', '{"json": "{\"pharm|1차|이만기\":{\"summary\":\"혼자 다른 교과서를 사용합니다. 여러분들 수업에도 계실지는 모르겠지만 선배들 후기를 살펴보면 원래는 교과서 퀴즈를 다 태웠으나 AI의 발전으로 문제를 AI로 출제하신다고,, 거의 유일하게 야마도 없이 참공부해야하는 것 같으나 그래도 교과서 퀴즈 구해서 푸신다면 어느 정도는 풀 수 있는 문제가 나올 거예요.\"}}", "updatedAt": "2026-11-13T07:24:56.690Z"}'::jsonb, 'evenstar1031', now())
